# o6_16 – Teilnahmevoraussetzungen, Vertragszeitraum und Beantragung
package oepul.o6_16

# ---------------------------------------------------------------------------
# 3.1 Vertragszeitraum
# ---------------------------------------------------------------------------

contract_period_years(start_year) := row.years if {
	some row in params.contract_period.rows
	row.start_year == start_year
}

contract_end_date := params.contract_period.end_date

# Die Option AG sowie die Zuschläge Schweinefütterung und Cultan laufen je ein Kalenderjahr.
component_contract_is_one_year(component) if component in {c | some c in params.contract_period.one_year_components}

# Der Zuschlag stark stickstoffreduzierte Fütterung verlängert sich automatisch, wenn er nicht abgemeldet wird.
pig_feeding_auto_renewed if {
	option_applied("n_reduced_pig_feeding")
	object.get(o16, ["n_reduced_pig_feeding", "deregistered"], false) == false
}

# ---------------------------------------------------------------------------
# 3.2 Kombinationsverpflichtung
# ---------------------------------------------------------------------------

combination_obligation_met if {
	some m in params.combination_obligation_measures
	participates(m)
}

violations contains {
	"rule_id": "o6_16.access.combination_obligation",
	"parcel_id": null,
	"message": "Zeitgleiche Teilnahme an o6_6 (Zwischenfruchtanbau) oder o6_7 (System Immergrün) fehlt.",
} if {
	participates_o6_16
	not combination_obligation_met
}

participates_o6_16 if participates("o6_16")

participates_o6_16 if is_number(object.get(o16, "contract_start_year", null))

# ---------------------------------------------------------------------------
# 3.3 Mindestteilnahme
# ---------------------------------------------------------------------------

min_area_first_year_met if arable_in_area_ha >= params.min_area_first_year_ha

violations contains {
	"rule_id": "o6_16.access.min_area_first_year",
	"parcel_id": null,
	"message": sprintf("Im ersten Teilnahmejahr nur %v ha Ackerfläche in der Gebietskulisse (mindestens 2,00 ha).", [arable_in_area_ha]),
} if {
	first_participation_year
	not min_area_first_year_met
}

# Schweine-GVE gemäß Anhang A (Jahresdurchschnitt)
pig_gve_factor := {row.code: row.gve_per_head |
	some row in data.o6_16.gve_schluessel_anhang_a.rows
	row.group == "schweine"
}

pig_group_gve(sg) := sg.gve if {
	is_number(object.get(sg, "gve", null))
} else := sg.animal_count * pig_gve_factor[sg.category]

pig_groups := [sg | some sg in object.get(input, ["livestock", "species_groups"], []); sg.species == "pigs"]

pig_gve_total := sum([g | some sg in pig_groups; g := pig_group_gve(sg)])

pig_gve_per_ha_arable := pig_gve_total / farm_arable_ha if farm_arable_ha > 0

pig_feeding_min_density_met if pig_gve_per_ha_arable >= params.pig_feeding_min_gve_per_ha_arable

violations contains {
	"rule_id": "o6_16.access.pig_feeding_min_density",
	"parcel_id": null,
	"message": "Zuschlag stark stickstoffreduzierte Fütterung: weniger als 1,00 GVE Schweine je ha Ackerfläche im Jahresdurchschnitt.",
} if {
	option_applied("n_reduced_pig_feeding")
	not pig_feeding_min_density_met
}

missing_data contains {"rule_id": "o6_16.access.pig_feeding_min_density", "path": "livestock.species_groups[].gve", "reason": "Schweinegruppe ohne GVE und ohne Kategorie gemäß Anhang A"} if {
	option_applied("n_reduced_pig_feeding")
	some sg in pig_groups
	not pig_group_gve(sg)
}

# Optionen AG und Cultan: mindestens ein Schlag
violations contains {
	"rule_id": "o6_16.access.option_min_one_parcel",
	"parcel_id": null,
	"message": sprintf("Option %v beantragt, aber kein entsprechend codierter Schlag vorhanden.", [name]),
} if {
	some name in ["leaching_risk_area", "cultan"]
	option_applied(name)
	count(option_parcels(name)) < params.options_min_parcels[name]
}

option_parcels("leaching_risk_area") := ag_parcels

option_parcels("cultan") := cul_parcels

# ---------------------------------------------------------------------------
# 5 Beantragung
# ---------------------------------------------------------------------------

application_deadline_for_start(start_year) := md_date(start_year - 1, params.application.measure_application_deadline_month_day)

application_in_time(application_date, start_year) if date_le(application_date, application_deadline_for_start(start_year))

violations contains {
	"rule_id": "o6_16.application.measure_application_deadline",
	"parcel_id": null,
	"message": "Maßnahmenantrag nicht bis 31.12. vor Vertragsbeginn gestellt.",
} if {
	is_date(o16.measure_application_date)
	not application_in_time(o16.measure_application_date, contract_start_year)
}

violations contains {
	"rule_id": "o6_16.application.last_entry_measure",
	"parcel_id": null,
	"message": "Einstieg in die Maßnahme nach dem Förderjahr 2025 nicht mehr möglich.",
} if {
	contract_start_year > params.application.last_entry_year_measure
}

violations contains {
	"rule_id": "o6_16.application.humus_vienna_application",
	"parcel_id": null,
	"message": "Zuschlag Humusaufbau und Erosionsschutz in Wien: Einstieg nur bis Förderjahr 2025 mit Maßnahmenantrag bis 31.12. des Vorjahres.",
} if {
	option_applied("humus_erosion_vienna")
	start := object.get(o16, ["humus_erosion_vienna", "start_year"], contract_start_year)
	humus_vienna_application_invalid(start)
}

humus_vienna_application_invalid(start) if start > params.application.last_entry_year_humus_vienna

humus_vienna_application_invalid(start) if {
	d := o16.humus_erosion_vienna.application_date
	is_date(d)
	not application_in_time(d, start)
}

violations contains {
	"rule_id": "o6_16.application.pig_feeding_application",
	"parcel_id": null,
	"message": "Zuschlag stark stickstoffreduzierte Fütterung: Einstieg spätestens Förderjahr 2028, Maßnahmenantrag bis 31.12. des Vorjahres (spätestens 31.12.2027).",
} if {
	option_applied("n_reduced_pig_feeding")
	start := object.get(o16, ["n_reduced_pig_feeding", "start_year"], year)
	pig_feeding_application_invalid(start)
}

pig_feeding_application_invalid(start) if start > params.application.last_entry_year_pig_feeding

pig_feeding_application_invalid(start) if {
	d := o16.n_reduced_pig_feeding.application_date
	is_date(d)
	not application_in_time(d, start)
}

violations contains {
	"rule_id": "o6_16.application.pig_feeding_not_with_o6_9",
	"parcel_id": null,
	"message": "Zuschlag stark stickstoffreduzierte Fütterung nicht gleichzeitig mit der gleichlautenden Kategorie der Maßnahme o6_9 möglich.",
} if {
	option_applied("n_reduced_pig_feeding")
	participates(params.pig_feeding_excluded_with)
}

# AG-Schläge: zulässige Schlagnutzungsarten
violations contains {
	"rule_id": "o6_16.application.ag_usage_type",
	"parcel_id": p.parcel_id,
	"message": "AG-Schlag muss als Grünbrache, Futtergräser, Sonstiges Feldfutter oder Wechselwiese beantragt werden.",
} if {
	some p in ag_parcels
	not object.get(p, ["oepul", "usage_type"], "") in {u | some u in params.application.ag_allowed_usage_types}
}

# AG + DIV nur bei Teilnahme an UBB oder BIO und nur als Grünbrache oder Sonstiges Feldfutter
violations contains {
	"rule_id": "o6_16.application.ag_div_double_coding",
	"parcel_id": p.parcel_id,
	"message": "AG-Schlag mit DIV-Code nur bei Teilnahme an UBB (o6_1a) oder BIO (o6_1b) und Schlagnutzung Grünbrache oder Sonstiges Feldfutter.",
} if {
	some p in ag_parcels
	has_code(p, "DIV")
	not ag_div_allowed(p)
}

ag_div_allowed(p) if {
	some m in params.application.ag_div_measures
	participates(m)
	object.get(p, ["oepul", "usage_type"], "") in {u | some u in params.application.ag_div_allowed_usage_types}
}

# AG + NPF bis 2024: Anrechnung GLÖZ 8, aber keine ÖPUL-Prämie
ag_npf_no_premium(p) if {
	is_ag(p)
	has_code(p, "NPF")
	year <= params.application.npf_until_year
}

# Umwandlung von AG-Flächen in Naturschutz/EBW bis 31.12.2025 (Maßnahmenantrag)
ag_conversion_possible(target, application_date) if {
	target in {t | some t in params.application.ag_conversion_targets}
	date_le(application_date, params.application.ag_conversion_deadline)
}

# Keine Maßnahmenantragspflicht vor Vertragsbeginn für AG und Cultan
requires_measure_application(component) if component in {c | some c in params.application.components_requiring_measure_application}

# o6_16 – anwendbare allgemeine Teilnahmebedingungen ÖPUL 2023
package oepul.o6_16

# ---------------------------------------------------------------------------
# 5.2 Förderwerbende Personen (Gebietskörperschaften ausgeschlossen, o6_16 nicht in der Ausnahmeliste)
# ---------------------------------------------------------------------------

public_body_excluded_for(measure, yr, share) if {
	share > general.public_body_max_share_percent
	not public_body_exception(measure, yr)
}

public_body_exception(measure, yr) if {
	some e in general.public_body_exception_measures
	e.measure_id == measure
	not year_before(yr, e.from_year)
	not year_after(yr, e.until_year)
}

year_before(yr, from) if {
	is_number(from)
	yr < from
}

year_after(yr, until) if {
	is_number(until)
	yr > until
}

violations contains {
	"rule_id": "o6_16.general.applicant_public_body",
	"parcel_id": null,
	"message": "Gebietskörperschaften bzw. Einrichtungen mit mehr als 25 % Beteiligung von Gebietskörperschaften sind für o6_16 nicht förderwerbend.",
} if {
	participates_o6_16
	public_body_excluded_for("o6_16", year, object.get(input, ["farm", "applicant", "public_body_share_percent"], 0))
}

violations contains {
	"rule_id": "o6_16.general.applicant_type",
	"parcel_id": null,
	"message": "Rechtsform der förderwerbenden Person nicht zulässig.",
} if {
	participates_o6_16
	lf := input.farm.applicant.legal_form
	not lf in {t | some t in general.applicant_types}
}

# ---------------------------------------------------------------------------
# 5.3 Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr
# ---------------------------------------------------------------------------

min_farm_size_met if object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= general.min_farm_size_first_year.protected_cultivation_ha

min_farm_size_met if object.get(input, ["land", "total_area_ha"], 0) >= general.min_farm_size_first_year.agricultural_area_ha

violations contains {
	"rule_id": "o6_16.general.min_farm_size",
	"parcel_id": null,
	"message": "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr (1,50 ha bzw. 0,50 ha geschützter Anbau) nicht erreicht.",
} if {
	object.get(input, ["farm", "oepul", "first_oepul_participation_year"], null) == year
	not min_farm_size_met
}

# ---------------------------------------------------------------------------
# 5.4/5.5 Mindestbewirtschaftung auf Ackerflächen (AG ausgenommen), Dürre-Ausnahme 2026
# ---------------------------------------------------------------------------

harvest_share(p) := object.get(p, ["harvest", "harvested_share"], null)

violations contains {
	"rule_id": "o6_16.general.minimum_management_harvest",
	"parcel_id": p.parcel_id,
	"message": sprintf("Ernte und Verbringen des Erntegutes auf nur %v des Schlages (mindestens 85 %%); Code OP erforderlich.", [harvest_share(p)]),
} if {
	some p in basis_parcels
	not is_arable_forage(p)
	is_number(harvest_share(p))
	harvest_share(p) < general.mindestbewirtschaftung.arable_harvest_min_share
	not drought_harvest_relief_applies(p)
}

# ---------------------------------------------------------------------------
# 5.9/6 Vertragszeitraum mehrjähriger Maßnahmen, Abmeldung
# ---------------------------------------------------------------------------

is_multi_year_measure(m) if m in {x | some x in general.multi_year_measures_until_2028}

# Abmeldung: im Zeitraum 1.1.-31.12. -> Maßnahme im betroffenen Förderjahr nicht gültig
deregistration_effective_year(deregistration_date) := date_year(deregistration_date)

# Ausstieg aus mehrjährigen Maßnahmen vor Vertragsende -> Rückforderung
early_exit_repayment(exit_year) if exit_year <= params.contract_period.end_year

# ---------------------------------------------------------------------------
# 6.2 Maßnahmenwechsel (AG -> Naturschutz/EBW) bis 31.12.2025
# ---------------------------------------------------------------------------

conversion_allowed(from, to, application_date) if {
	some c in general.measure_conversions
	c.from == from
	to in {t | some t in c.to}
	date_le(application_date, general.measure_conversion_latest)
}

# ---------------------------------------------------------------------------
# 6.3 Maßnahmenübernahme
# ---------------------------------------------------------------------------

takeover_deadline(yr) := md_date(yr, general.takeover.deadline_month_day_2023_2028) if yr in {2023, 2028}

takeover_deadline(yr) := md_date(yr, general.takeover.deadline_month_day) if not yr in {2023, 2028}

takeover_individual_cases_only(component) if component in {x | some x in general.takeover_individual_cases_only}

takeover_extension_ok(taken_over_ha, extension_ha) if extension_ha <= general.takeover.max_extension_share * taken_over_ha

# ---------------------------------------------------------------------------
# 7.1 Flächenabgang – Toleranz
# ---------------------------------------------------------------------------

allowed_area_reduction(previous_ha) := max([
	min([general.area_reduction_tolerance.max_share * previous_ha, general.area_reduction_tolerance.max_ha]),
	general.area_reduction_tolerance.always_allowed_ha,
])

area_reduction_repayment_required(previous_ha, current_ha) if previous_ha - current_ha > allowed_area_reduction(previous_ha)

violations contains {
	"rule_id": "o6_16.general.area_reduction_tolerance",
	"parcel_id": null,
	"message": sprintf("Flächenverringerung von %v ha auf %v ha übersteigt die Toleranz; Rückzahlung für die gesamte Differenzfläche.", [prev, basis_parcels_ha]),
} if {
	prev := o16.premium_area_previous_year_ha
	is_number(prev)
	not object.get(o16, "area_reduction_due_to_loss_of_control", false) == true
	area_reduction_repayment_required(prev, basis_parcels_ha)
}

# ---------------------------------------------------------------------------
# 7.2 Flächenzugang – Prämienfähigkeit (ab 2026 max. +50 % auf Basis 2025, mind. +5 ha)
# ---------------------------------------------------------------------------

limited_increase_area(current_ha, _, yr) := current_ha if yr in {y | some y in general.area_increase.fully_eligible_years}

limited_increase_area(current_ha, _, yr) := current_ha if yr < general.area_increase.base_year

limited_increase_area(current_ha, base_2025_ha, yr) := min([current_ha, base_2025_ha + max([general.area_increase.max_share * base_2025_ha, general.area_increase.always_allowed_ha])]) if yr > general.area_increase.base_year

# ---------------------------------------------------------------------------
# 8.2 Sanktionsstufen
# ---------------------------------------------------------------------------

sanction_reduction_percent(stage, yr) := s.reduction_percent if {
	yr < 2027
	some s in general.sanction_stages
	s.stage == stage
}

sanction_reduction_percent(stage, yr) := s.reduction_percent_from_2027 if {
	yr >= 2027
	some s in general.sanction_stages
	s.stage == stage
}

# ---------------------------------------------------------------------------
# 9.1-9.3 Auszahlung, Obergrenzen, Modulation
# ---------------------------------------------------------------------------

payment_deadline(yr) := md_date(yr + 1, general.payment_deadline_month_day_next_year)

max_advance_payment(expected_eur) := expected_eur * general.advance_payment_max_share

payout_may_be_withheld(amount_eur) if amount_eur <= general.min_payout_eur

area_payment_cap(scope, yr) := c.eur_per_ha if {
	some c in general.area_payment_caps
	c.scope == scope
	c.year_from <= yr
	yr <= c.year_to
}

area_payment_cap_exceeded(sum_eur_per_ha, scope, yr) if sum_eur_per_ha > area_payment_cap(scope, yr)

band_portion(total_ha, band) := max([0, min([total_ha, band.to_ha]) - band.from_ha]) if is_number(band.to_ha)

band_portion(total_ha, band) := max([0, total_ha - band.from_ha]) if band.to_ha == null

modulation_factor(total_ha) := 1 if total_ha <= 0

modulation_factor(total_ha) := sum([x |
	some b in general.modulation_bands
	x := band_portion(total_ha, b) * b.payout_share
]) / total_ha if {
	total_ha > 0
}

# ---------------------------------------------------------------------------
# 5.7 Tierhaltender Betrieb (allgemeine Definition)
# ---------------------------------------------------------------------------

livestock_farm(rgve, forage_ha) if {
	forage_ha > 0
	rgve / forage_ha >= general.livestock_farm_min_rgve_per_ha_forage
}

# o6_16 – Stickstoffbilanzierung und Übertrag auf die Folgekultur (4.3)
package oepul.o6_16

# Schwellenwert/Obergrenze je Antragsjahr der Folgekultur
carryover_row(yr) := row if {
	some row in params.n_carryover.threshold_rows
	row.year_from <= yr
	yr <= row.year_to
}

# Ist der Stickstoffüberschuss (vor Abzug des Reduktionsfaktors) anzurechnen?
carryover_required(saldo, yr) if saldo > carryover_row(yr).threshold_kg_ha_exclusive

# anzurechnender Überschuss: ab 2025 max. 100 kg N/ha vor Reduktionsfaktor (auch bei Schadereignissen)
capped_surplus(saldo, yr) := min([saldo, carryover_row(yr).cap_kg_ha]) if is_number(carryover_row(yr).cap_kg_ha)

capped_surplus(saldo, yr) := saldo if carryover_row(yr).cap_kg_ha == null

reduction_factor(zone) := row.factor if {
	some row in params.n_carryover.reduction_factor_zones
	row.zone == zone
}

# Zone eines Schlages: Wien ergibt sich aus Anhang G, sonst Profilangabe
parcel_zone(p) := "wien" if in_vienna_area(p)

parcel_zone(p) := p.n_reduction_zone if {
	not in_vienna_area(p)
	is_string(object.get(p, "n_reduction_zone", null))
}

# Mindestreduktion der Düngung der Folgekultur (kg N/ha)
required_n_reduction(saldo, yr, _) := 0 if not carryover_required(saldo, yr)

required_n_reduction(saldo, yr, zone) := round((capped_surplus(saldo, yr) * reduction_factor(zone)) * 100) / 100 if carryover_required(saldo, yr)

parcel_saldo(p) := p.previous_crop.n_saldo_kg_ha if is_number(object.get(p, ["previous_crop", "n_saldo_kg_ha"], null))

parcel_required_reduction(p) := required_n_reduction(parcel_saldo(p), year, parcel_zone(p))

n_carryover := {p.parcel_id: parcel_required_reduction(p) | some p in arable_in_area}

missing_data contains {"rule_id": "o6_16.n.carryover_reduction", "path": "land.parcels[].n_reduction_zone", "reason": sprintf("Schlag %v: Reduktionszone (80 %%/60 %%) nicht bestimmbar", [p.parcel_id])} if {
	some p in arable_in_area
	carryover_required(parcel_saldo(p), year)
	not parcel_zone(p)
}

# Düngung der Folgekultur ist um den Übertrag einzuschränken
violations contains {
	"rule_id": "o6_16.n.carryover_reduction",
	"parcel_id": p.parcel_id,
	"message": sprintf("Düngung der Folgekultur %v kg N/ha überschreitet Bedarf %v abzüglich Übertrag %v.", [fert, need, red]),
} if {
	some p in arable_in_area
	red := parcel_required_reduction(p)
	fert := p.n_management.follow_crop_n_fertilization_kg_ha
	need := p.n_management.follow_crop_n_requirement_kg_ha
	is_number(fert)
	is_number(need)
	fert > need - red
}

# Ungenutzte Zwischenfrucht: max. Düngung = Düngebedarf Folgekultur - Übertrag aus Vorkultur
max_unused_cover_crop_n(follow_need, transfer) := max([0, follow_need - transfer])

violations contains {
	"rule_id": "o6_16.n.unused_cover_crop_max",
	"parcel_id": p.parcel_id,
	"message": sprintf("Düngung der ungenutzten Zwischenfrucht %v kg N/ha über zulässigem Maximum %v.", [cc, maxn]),
} if {
	some p in arable_in_area
	cc := p.n_management.unused_cover_crop_n_kg_ha
	is_number(cc)
	maxn := max_unused_cover_crop_n(p.n_management.follow_crop_n_requirement_kg_ha, parcel_required_reduction(p))
	cc > maxn
}

# Reduktionsfaktor zwischen zwei Hauptkulturen nur einmal
violations contains {
	"rule_id": "o6_16.n.reduction_factor_once",
	"parcel_id": p.parcel_id,
	"message": "Reduktionsfaktor zwischen zwei Hauptkulturen mehr als einmal angewendet.",
} if {
	some p in arable_in_area
	object.get(p, ["n_management", "reduction_factor_applications"], 0) > params.n_carryover.max_reduction_factor_applications_between_main_crops
}

# Körnerleguminosen und Ackerfutter: Stickstoffbedarf statt ertragsabhängigem Entzug
legume_or_forage(pc) if object.get(pc, "crop_category", "") == "legume"

legume_or_forage(pc) if is_arable_forage_name(object.get(pc, "crop_name", ""))

violations contains {
	"rule_id": "o6_16.n.legume_offtake_basis",
	"parcel_id": p.parcel_id,
	"message": "Bei Körnerleguminosen/Ackerfutter ist im Saldo der Stickstoffbedarf statt des ertragsabhängigen Entzugs anzusetzen.",
} if {
	some p in arable_in_area
	legume_or_forage(object.get(p, "previous_crop", {}))
	object.get(p, ["n_management", "offtake_basis"], "") == "yield_based"
}

# Gemüse nach Gemüse mit Nmin-Analyse: Abzug mindestens in Höhe des Saldos der Vorkultur
vegetable_n_deduction(nmin, saldo) := max([nmin, saldo])

# ---------------------------------------------------------------------------
# Herbst-Anlageverpflichtung (Folgekultur bis 15.11. oder Zwischenfrucht o6_6/o6_7)
# ---------------------------------------------------------------------------

autumn := params.n_carryover.autumn_obligation

is_vegetable_or_pumpkin(pc) if object.get(pc, "crop_category", "") == "vegetable"

is_vegetable_or_pumpkin(pc) if name_in(object.get(pc, "crop_name", ""), general.definitions.feldgemuese)

is_vegetable_or_pumpkin(pc) if name_in(object.get(pc, "crop_name", ""), autumn.pumpkin_crop_names)

is_forage_or_fallow(pc) if object.get(pc, "crop_category", "") == "fallow"

is_forage_or_fallow(pc) if is_arable_forage_name(object.get(pc, "crop_name", ""))

harvested_late(pc) if {
	d := pc.harvest_date
	is_date(d)
	month_day(d) > autumn.late_harvest_after_month_day
}

# Auslöser, die durch späte Ernte (nach 30.09.) aufgehoben werden
autumn_trigger_harvest(p) if parcel_saldo(p) > autumn.saldo_threshold_kg_ha_exclusive

autumn_trigger_harvest(p) if {
	is_vegetable_or_pumpkin(object.get(p, "previous_crop", {}))
	p.area_ha > autumn.vegetable_pumpkin_min_parcel_ha_exclusive
}

# Umbruch von Ackerfutter oder Ackerbrache vor dem 15.11.
autumn_trigger_breakup(p) if {
	pc := object.get(p, "previous_crop", {})
	is_forage_or_fallow(pc)
	d := pc.breakup_date
	is_date(d)
	date_lt(d, md_date(date_year(d), autumn.deadline_month_day))
}

autumn_obligation_applies(p) if autumn_trigger_breakup(p)

autumn_obligation_applies(p) if {
	autumn_trigger_harvest(p)
	not harvested_late(object.get(p, "previous_crop", {}))
}

autumn_obligation_fulfilled(p) if {
	d := p.n_management.follow_crop_sowing_date
	is_date(d)
	date_le(d, md_date(autumn_reference_year(p), autumn.deadline_month_day))
}

autumn_obligation_fulfilled(p) if {
	object.get(p, ["operations", "cover_crop", "is_used"], false) == true
	some m in params.combination_obligation_measures
	participates(m)
}

autumn_reference_year(p) := date_year(p.previous_crop.breakup_date) if is_date(object.get(p, ["previous_crop", "breakup_date"], null))

autumn_reference_year(p) := date_year(p.previous_crop.harvest_date) if {
	not is_date(object.get(p, ["previous_crop", "breakup_date"], null))
	is_date(object.get(p, ["previous_crop", "harvest_date"], null))
}

autumn_reference_year(p) := year if {
	not is_date(object.get(p, ["previous_crop", "breakup_date"], null))
	not is_date(object.get(p, ["previous_crop", "harvest_date"], null))
}

violations contains {
	"rule_id": "o6_16.n.autumn_sowing_obligation",
	"parcel_id": p.parcel_id,
	"message": "Anlage einer Folgekultur bis 15.11. oder einer Zwischenfrucht gemäß o6_6/o6_7 erforderlich.",
} if {
	some p in arable_in_area
	autumn_obligation_applies(p)
	not autumn_obligation_fulfilled(p)
}

# o6_16 – relevante AMA-Hinweise 2026 (Dürre, Begrünung, Biodiversitätsflächen)
package oepul.o6_16

# ---------------------------------------------------------------------------
# Dürre 2026: Entfall der Ernteverpflichtung in festgelegten Bezirken (05.08./12.08.2026)
# ---------------------------------------------------------------------------

drought_relief_district(state, district) if {
	some row in notices.drought_harvest_relief_2026.districts
	row.bundesland == state
	row.all_districts == true
	is_string(district)
}

drought_relief_district(state, district) if {
	some row in notices.drought_harvest_relief_2026.districts
	row.bundesland == state
	name_in(district, row.districts)
}

drought_harvest_relief_applies(p) if {
	year == notices.drought_harvest_relief_2026.year
	drought_relief_district(area_state(p), input.farm.region.district)
	object.get(p, ["harvest", "no_harvestable_stand_due_to_drought"], false) == true
	object.get(p, ["harvest", "usually_harvested_late_summer_or_autumn"], true) == true
}

# ---------------------------------------------------------------------------
# Begrünung (Kombinationsverpflichtung o6_6/o6_7): Flächendeckung 2026 nicht beanstandet
# ---------------------------------------------------------------------------

greening_coverage_relief(yr, measure, properly_sown) if {
	yr == notices.greening_coverage_relief_2026.year
	measure in {m | some m in notices.greening_coverage_relief_2026.measures}
	properly_sown == true
}

# o6_6 Varianten 1/2: späteste Anlage 2026
o6_6_latest_sowing_2026(variant) := row.latest_sowing if {
	some row in notices.o6_6_variant_deadlines_2026
	row.variant == variant
}

# o6_7: Fristen 30/50 Tage dürfen 2026 überschritten werden; Zwischenfrucht dennoch bis 20.09./15.10.
o6_7_latest_cover_crop_2026(frost_killed) := notices.o6_7_deadline_relief_2026.frost_killed_mix_latest if frost_killed == true

o6_7_latest_cover_crop_2026(frost_killed) := notices.o6_7_deadline_relief_2026.winter_hardy_latest if frost_killed == false

# ---------------------------------------------------------------------------
# AG-Schläge mit DIV-Code: vorzeitige bzw. dritte Nutzung 2026 nur mit OPUBB/OPBIO
# ---------------------------------------------------------------------------

div_relief := notices.arable_div_relief_2026

op_div_coded(p) if {
	some c in div_relief.required_codes
	has_code(p, c)
}

uses_in_year(p, yr) := count([d | some d in object.get(p, ["operations", "cutting_dates"], []); date_year(d) == yr])

early_use(p, yr) if {
	some d in object.get(p, ["operations", "cutting_dates"], [])
	date_year(d) == yr
	month_day(d) < div_relief.regular_earliest_month_day
}

arable_div_parcels := [p | some p in parcels; is_arable(p); has_code(p, "DIV")]

arable_div_ha := sum([p.area_ha | some p in arable_div_parcels])

early_used_uncoded_div_ha := sum([p.area_ha | some p in arable_div_parcels; early_use(p, year); not op_div_coded(p)])

violations contains {
	"rule_id": "o6_16.notice2026.div_early_use",
	"parcel_id": null,
	"message": "Acker-Biodiversitätsflächen (inkl. AG+DIV) vor dem 1. August über den 25-%-Anteil hinaus genutzt ohne Code OPUBB/OPBIO.",
} if {
	year == div_relief.year
	early_used_uncoded_div_ha > div_relief.regular_unrestricted_share * arable_div_ha
}

violations contains {
	"rule_id": "o6_16.notice2026.div_third_use",
	"parcel_id": p.parcel_id,
	"message": "Dritte Nutzung einer Acker-Biodiversitätsfläche 2026 nur mit Code OPUBB/OPBIO (ohne Prämie).",
} if {
	year == div_relief.year
	some p in arable_div_parcels
	uses_in_year(p, year) > div_relief.max_uses_regular
	not op_div_coded(p)
}

# o6_16 – Option AG (4.8), Zuschläge Wien (4.9), Schweinefütterung (4.10) und Cultan (4.11)
package oepul.o6_16

# ---------------------------------------------------------------------------
# 4.8 Option Bewirtschaftung auswaschungsgefährdeter Ackerflächen (Code AG)
# ---------------------------------------------------------------------------

ag := params.leaching_risk_area

ag_option(p) := object.get(p, "leaching_option", {})

ag_first_year(p) := object.get(ag_option(p), "previous_farm_first_ag_year", null) if {
	is_number(object.get(ag_option(p), "previous_farm_first_ag_year", null))
} else := object.get(ag_option(p), "first_ag_year", year)

# Schlag-Eignung
ag_parcel_eligible(p) if {
	in_area(p)
	is_arable(p)
	ackerzahl := object.get(ag_option(p), "ackerzahl_avg", null)
	is_number(ackerzahl)
	ackerzahl <= ag.max_avg_ackerzahl
	object.get(ag_option(p), "grassland_in_mfa_2020", false) == false
	not ag_npf_no_premium(p)
}

violations contains {
	"rule_id": "o6_16.ag.eligibility",
	"parcel_id": p.parcel_id,
	"message": "AG-Schlag nicht förderfähig (außerhalb Gebietskulisse, Ackerzahl > 40 bzw. unbekannt oder im MFA 2020 Grünland).",
} if {
	some p in ag_parcels
	not ag_parcel_eligible(p)
	not ag_npf_no_premium(p)
}

# förderfähiges Ausmaß ohne GLÖZ-4-Pufferstreifen und (bis 2024) GLÖZ-8-Stilllegung
ag_eligible_area(p) := max([0, (p.area_ha - object.get(ag_option(p), "gloez4_area_ha", 0)) - gloez8_deduction(p)])

gloez8_deduction(p) := object.get(ag_option(p), "gloez8_area_ha", 0) if year <= params.application.npf_until_year

gloez8_deduction(_) := 0 if year > params.application.npf_until_year

# Einsaat winterharte Mischung ohne Leguminosen bis 15.05. oder Belassen eines Bestandes
ag_establishment_ok(p) if {
	object.get(ag_option(p), "existing_stand_retained", false) == true
	object.get(p, ["oepul", "usage_type"], "") in {u | some u in ag.existing_stand_usage_types}
}

ag_establishment_ok(p) if {
	d := ag_option(p).sowing_date
	is_date(d)
	date_le(d, md_date(date_year(d), ag.sowing_deadline_month_day))
	ag_option(p).mix_winter_hardy == true
	ag_option(p).mix_contains_legumes == false
}

violations contains {
	"rule_id": "o6_16.ag.establishment",
	"parcel_id": p.parcel_id,
	"message": "AG: Einsaat einer winterharten Begrünungsmischung ohne Leguminosen bis 15.05. bzw. Belassen eines Grünbrache-/Ackerfutterbestandes fehlt.",
} if {
	some p in ag_parcels
	ag_first_year(p) == year
	not ag_establishment_ok(p)
}

# Umbruch frühestens am 15.09. des 2. Jahres (betriebsübergreifend gerechnet)
ag_earliest_breakup(p) := md_date(ag_first_year(p) + 1, ag.earliest_breakup_month_day_second_year)

violations contains {
	"rule_id": "o6_16.ag.breakup_date",
	"parcel_id": p.parcel_id,
	"message": sprintf("AG: Umbruch am %v vor dem frühestmöglichen Termin %v.", [d, ag_earliest_breakup(p)]),
} if {
	some p in ag_parcels
	d := ag_option(p).breakup_date
	is_date(d)
	date_lt(d, ag_earliest_breakup(p))
}

# kein Einsatz von Pflanzenschutz- und Düngemitteln
ag_inputs_used(p) if object.get(p, ["operations", "psm_used"], false) == true

ag_inputs_used(p) if count(psm_applications(p)) > 0

ag_inputs_used(p) if count(fertilizer_applications(p)) > 0

ag_inputs_used(p) if object.get(p, ["operations", "fertilizer", "mineral_n_kg_per_ha"], 0) > 0

ag_inputs_used(p) if object.get(p, ["operations", "fertilizer", "organic_n_kg_per_ha"], 0) > 0

violations contains {
	"rule_id": "o6_16.ag.no_psm_no_fertilizer",
	"parcel_id": p.parcel_id,
	"message": "AG: Einsatz von Pflanzenschutz- oder Düngemitteln ab 1.1. des ersten AG-Jahres nicht erlaubt.",
} if {
	some p in ag_parcels
	ag_inputs_used(p)
}

# Mahd/Häckseln mindestens einmal jedes zweite Jahr
ag_mown_in(p, yr) if yr in {y | some y in object.get(ag_option(p), "mowing_or_mulching_years", [])}

ag_mown_in(p, yr) if {
	some d in object.get(p, ["operations", "cutting_dates"], [])
	date_year(d) == yr
}

violations contains {
	"rule_id": "o6_16.ag.mowing_every_second_year",
	"parcel_id": p.parcel_id,
	"message": "AG: Mahd oder Häckseln mindestens einmal jedes zweite Jahr fehlt.",
} if {
	some p in ag_parcels
	year >= ag_first_year(p) + 1
	not ag_mown_in(p, year)
	not ag_mown_in(p, year - 1)
}

violations contains {
	"rule_id": "o6_16.ag.no_grazing_no_threshing",
	"parcel_id": p.parcel_id,
	"message": "AG: Beweidung und Drusch sind nicht erlaubt.",
} if {
	some p in ag_parcels
	ag_grazed_or_threshed(p)
}

ag_grazed_or_threshed(p) if object.get(ag_option(p), "grazed", false) == true

ag_grazed_or_threshed(p) if object.get(ag_option(p), "threshed", false) == true

# Prämienfläche AG: max. 20 % der Ackerfläche des Betriebes
ag_premium_area_uncapped := sum([ag_eligible_area(p) | some p in ag_parcels; ag_parcel_eligible(p)])

ag_premium_area := min([ag_premium_area_uncapped, ag.premium_max_share_of_farm_arable * farm_arable_ha])

# ---------------------------------------------------------------------------
# 4.9 Zuschlag Humusaufbau und Erosionsschutz in Wien
# ---------------------------------------------------------------------------

humus_vienna if option_applied("humus_erosion_vienna")

violations contains {
	"rule_id": "o6_16.vienna.area_required",
	"parcel_id": null,
	"message": "Zuschlag Humusaufbau und Erosionsschutz in Wien setzt Ackerflächen in der Gebietskulisse Wien voraus.",
} if {
	humus_vienna
	count(vienna_arable) == 0
}

previous_crop_maize(p) if object.get(p, ["previous_crop", "crop_category"], "") == "maize"

previous_crop_maize(p) if name_in(object.get(p, ["previous_crop", "crop_name"], ""), ["Mais", "Körnermais", "Silomais", "Corn-Cob-Mix", "Zuckermais", "Saatmaisvermehrung"])

violations contains {
	"rule_id": "o6_16.vienna.no_inversion_tillage",
	"parcel_id": p.parcel_id,
	"message": "Wendende Bodenbearbeitung auf Ackerflächen der Gebietskulisse Wien unzulässig (ausgenommen nach Mais).",
} if {
	humus_vienna
	some p in vienna_arable
	object.get(p, ["operations", "tillage_type"], "") == "plough"
	not previous_crop_maize(p)
}

violations contains {
	"rule_id": "o6_16.vienna.scientific_project",
	"parcel_id": null,
	"message": "Teilnahmebestätigung für das anerkannte Projekt (wissenschaftliche Begleitung) fehlt bzw. Daten nicht bereitgestellt.",
} if {
	humus_vienna
	not vienna_project_ok
}

vienna_project_ok if {
	o16.humus_erosion_vienna.project_confirmation == true
	object.get(o16, ["humus_erosion_vienna", "data_provided_on_request"], true) == true
}

vienna_training_fulfilled if vienna_extra_training_hours >= params.vienna_humus.extra_training_hours

violations contains {
	"rule_id": "o6_16.vienna.extra_training",
	"parcel_id": null,
	"message": "Zusätzliche 3 Stunden Bildung und Beratung (Bodenproben, Humusaufbau, pfluglose Bodenbearbeitung) nicht bis 31.12.2026 absolviert.",
} if {
	humus_vienna
	not vienna_training_fulfilled
	deadline_passed(params.training.deadline)
}

vienna_soil_samples_required := params.vienna_humus.soil_sample_multiplier * soil_samples_required(vienna_arable_ha)

vienna_creditable_samples := [s | some s in creditable_soil_samples; object.get(s, "area", "") == "wien_gebiet"]

violations contains {
	"rule_id": "o6_16.vienna.double_soil_samples",
	"parcel_id": null,
	"message": sprintf("Wien: %v Bodenproben erforderlich (2 je angefangene 5 ha), %v vorhanden.", [vienna_soil_samples_required, count(vienna_creditable_samples)]),
} if {
	humus_vienna
	count(vienna_creditable_samples) < vienna_soil_samples_required
	deadline_passed(params.soil_samples.deadline)
}

# Auf Wiener Teilnahmeflächen keine Prämie aus o6_8 für Mulchsaat, Direktsaat, Strip-Till
o6_8_premium_excluded contains p.parcel_id if {
	humus_vienna
	some p in vienna_arable
	some practice in object.get(p, ["oepul", "o6_8_practices"], [])
	practice in {x | some x in params.vienna_humus.excluded_o6_8_variants}
}

# ---------------------------------------------------------------------------
# 4.10 Zuschlag stark stickstoffreduzierte Fütterung von Schweinen
# ---------------------------------------------------------------------------

protein_limits(category) := [row | some row in params.crude_protein_limits; row.feeding_category == category]

average_limit(category) := row.max_g_per_kg_88_tm if {
	some row in protein_limits(category)
	row.basis == "average"
}

feeding(sg) := object.get(sg, "feeding", {})

# Durchschnittswert eingehalten
pig_group_average_ok(sg) if {
	cp := feeding(sg).crude_protein_avg_g_per_kg
	is_number(cp)
	cp <= average_limit(feeding(sg).feeding_category)
}

# Phasenfütterung (nur Jung-/Mastschweine, ungedeckte Jungsauen): jede Phase unter Höchstgrenze
phase_limit(category, phase) := row.max_g_per_kg_88_tm if {
	some row in protein_limits(category)
	row.basis == "phase"
	row.weight_from_kg == phase.weight_from_kg
}

pig_group_phase_ok(sg) if {
	feeding(sg).feeding_category == "jung_mast_jungsau_ungedeckt"
	feeding(sg).phase_feeding == true
	phases := feeding(sg).phases
	count(phases) > 0
	every ph in phases {
		ph.crude_protein_g_per_kg <= phase_limit(feeding(sg).feeding_category, ph)
	}
}

pig_group_protein_ok(sg) if pig_group_average_ok(sg)

pig_group_protein_ok(sg) if pig_group_phase_ok(sg)

violations contains {
	"rule_id": "o6_16.pig_feeding.crude_protein_limits",
	"parcel_id": null,
	"message": sprintf("Schweinegruppe %v: Rohproteingrenze (je kg bei 88 %% TM) nicht eingehalten.", [object.get(feeding(sg), "feeding_category", "?")]),
} if {
	option_applied("n_reduced_pig_feeding")
	some sg in pig_groups
	not pig_group_protein_ok(sg)
}

violations contains {
	"rule_id": "o6_16.pig_feeding.evidence",
	"parcel_id": null,
	"message": "Nachweis über Rezepturen mit ausgewiesenem Rohproteingehalt (88 % TM) bzw. Plausibilisierung der Phasenfütterung fehlt.",
} if {
	option_applied("n_reduced_pig_feeding")
	some sg in pig_groups
	not pig_feeding_evidence_ok(sg)
}

pig_feeding_evidence_ok(sg) if {
	feeding(sg).recipe_evidence_available == true
	not feeding(sg).phase_feeding == true
}

pig_feeding_evidence_ok(sg) if {
	feeding(sg).recipe_evidence_available == true
	feeding(sg).phase_feeding == true
	feeding(sg).phase_feeding_plausible == true
}

pig_feeding_eligible if {
	option_applied("n_reduced_pig_feeding")
	pig_feeding_min_density_met
	not participates(params.pig_feeding_excluded_with)
}

# ---------------------------------------------------------------------------
# 4.11 Zuschlag Cultan-Düngung (ab 2025)
# ---------------------------------------------------------------------------

cultan_applications(p) := [a | some a in fertilizer_applications(p); a.method == "cultan_injection"]

cultan_parcel_ok(p) if {
	year >= params.cultan.from_year
	in_area(p)
	is_arable(p)
	not is_ag(p)
	count(cultan_applications(p)) > 0
	every a in cultan_applications(p) {
		object.get(a, "recorded", false) == true
		cultan_contractor_ok(a)
	}
}

cultan_contractor_ok(a) if object.get(a, "external_contractor", false) == false

cultan_contractor_ok(a) if {
	a.external_contractor == true
	a.contractor_invoice_available == true
}

violations contains {
	"rule_id": "o6_16.cultan.requirements",
	"parcel_id": p.parcel_id,
	"message": "CUL-Schlag: keine dokumentierte Cultan-Injektion (Ammoniumdepot), fehlende Aufzeichnung oder fehlender Nachweis bei betriebsfremden Geräten bzw. außerhalb Gebietskulisse/vor 2025.",
} if {
	some p in cul_parcels
	not cultan_parcel_ok(p)
}

# o6_16 – Höhe der Prämie (6) inkl. Kombinations- und Ausschlussregeln
package oepul.o6_16

premium_rate(component, yr) := r.eur_per_ha if {
	some r in params.premium_rates
	r.component == component
	r.year_from <= yr
	yr <= r.year_to
}

round2(x) := round(x * 100) / 100

# Basisprämie: 50 % bei Teilnahme an Biologische Wirtschaftsweise (o6_1b) oder EEB (o6_2)
basis_component := "basis_reduced" if {
	some m in ["o6_1b", "o6_2"]
	participates(m)
}

basis_component := "basis" if {
	not participates("o6_1b")
	not participates("o6_2")
}

# Flächenzugangsbeschränkung (Allgemeine Bedingungen 7.2 / SRL 1.7.2.4)
basis_premium_area := limited_increase_area(basis_parcels_ha, o16.premium_area_2025_ha, year) if {
	is_number(object.get(o16, "premium_area_2025_ha", null))
} else := basis_parcels_ha

# Zuschlag Pflanzenschutzmittelverzicht: nicht mit BIO, nicht in Schutz- und Schongebieten
psm_premium_parcels(component) := [p |
	some p in basis_parcels
	name_in(crop_name(p), params.psm_premium_crops[component])
	object.get(p, ["oepul", "in_protection_or_conservation_zone"], false) == false
]

psm_premium_area(_) := 0 if participates("o6_1b")

psm_premium_area(component) := sum([p.area_ha | some p in psm_premium_parcels(component)]) if not participates("o6_1b")

ooe_top_up_area := 0 if object.get(o16, "upper_austria_top_up_funds_available", true) == false

ooe_top_up_area := sum([p.area_ha | some p in basis_parcels; in_upper_austria_area(p)]) if object.get(o16, "upper_austria_top_up_funds_available", true) != false

vienna_premium_area := sum([p.area_ha | some p in basis_parcels; in_vienna_area(p)]) if humus_vienna

vienna_premium_area := 0 if not humus_vienna

# bis 2024 nur Ackerflächen in der Gebietskulisse, ab 2025 alle Ackerflächen (ohne AG-Schläge)
pig_feeding_area := basis_parcels_ha if {
	pig_feeding_eligible
	year <= 2024
}

pig_feeding_area := sum([p.area_ha | some p in parcels; is_arable(p); not is_ag(p); not is_op(p)]) if {
	pig_feeding_eligible
	year >= 2025
}

pig_feeding_area := 0 if not pig_feeding_eligible

cultan_area := sum([p.area_ha | some p in cul_parcels; cultan_parcel_ok(p)])

premium_areas := {
	basis_component: basis_premium_area,
	"training_first_10ha": min([basis_premium_area, 10]),
	"psm_maize_sorghum": psm_premium_area("psm_maize_sorghum"),
	"psm_rape_seed_maize": psm_premium_area("psm_rape_seed_maize"),
	"upper_austria_top_up": ooe_top_up_area,
	"leaching_risk_area": ag_premium_area,
	"humus_erosion_vienna": vienna_premium_area,
	"n_reduced_pig_feeding": pig_feeding_area,
	"cultan": cultan_area,
}

premium_components[component] := {
	"area_ha": round2(area),
	"rate_eur_per_ha": rate,
	"amount_eur": round2(area * rate),
} if {
	some component, area in premium_areas
	rate := premium_rate(component, year)
}

premium_total_before_modulation := round2(sum([c.amount_eur | some c in premium_components]))

premium_total := round2(premium_total_before_modulation * modulation_factor(object.get(input, ["land", "total_area_ha"], 0)))

# Anhang L: Kombinierbarkeit auf der Einzelfläche (Zeile o6_16)
combination_cell(measure) := c.cell if {
	some c in data.o6_16.kombination_anhang_l.row_o6_16
	c.measure_id == measure
}

combinable_on_parcel(measure) if combination_cell(measure) in {"x", "a"}

combination_with_premium_deduction(measure) if combination_cell(measure) == "a"

# o6_16 – Pflanzenschutz (4.6) und zusätzliche Förderverpflichtungen in Oberösterreich (4.7)
package oepul.o6_16

# ---------------------------------------------------------------------------
# 4.6 Wirkstoffverbot in der Gebietskulisse
# ---------------------------------------------------------------------------

bentazon_reauthorized := o16.bentazon_reauthorized if {
	is_boolean(object.get(o16, "bentazon_reauthorized", null))
} else := params.psm.bentazon_reauthorized_default

banned_substances := {lower(s) | some s in params.psm.banned_active_substances} | conditional_banned

conditional_banned := {lower(c.substance) | some c in params.psm.conditional_banned_active_substances} if bentazon_reauthorized

conditional_banned := set() if not bentazon_reauthorized

psm_restricted_crop(p) if name_in(crop_name(p), params.psm.restricted_crops)

psm_restricted_crop(p) if is_maize(p)

psm_applications(p) := object.get(p, ["operations", "psm_applications"], [])

violations contains {
	"rule_id": "o6_16.psm.banned_active_substances",
	"parcel_id": p.parcel_id,
	"message": sprintf("Wirkstoff %v auf %v in der Gebietskulisse nicht zulässig.", [s, crop_name(p)]),
} if {
	some p in arable_in_area
	psm_restricted_crop(p)
	some a in psm_applications(p)
	some s in a.active_substances
	lower(s) in banned_substances
}

# Codierung PSMBIO/PSMCS im Mehrfachantrag bis einschließlich Antragsjahr 2025
psm_coding_required(yr) if yr <= params.psm.coding_until_year

required_psm_code(p) := "PSMCS" if {
	some a in psm_applications(p)
	a.product_type == "chemical_synthetic"
}

required_psm_code(p) := "PSMBIO" if {
	count(psm_applications(p)) > 0
	every a in psm_applications(p) {
		a.product_type == "bio"
	}
}

psm_code_ok(p) if has_code(p, "PSMCS")

psm_code_ok(p) if {
	required_psm_code(p) == "PSMBIO"
	has_code(p, "PSMBIO")
}

violations contains {
	"rule_id": "o6_16.psm.coding_until_2025",
	"parcel_id": p.parcel_id,
	"message": sprintf("Flächiger Pflanzenschutzmitteleinsatz: Code %v im Mehrfachantrag fehlt.", [required_psm_code(p)]),
} if {
	psm_coding_required(year)
	some p in arable_in_area
	required_psm_code(p)
	not psm_code_ok(p)
}

# ---------------------------------------------------------------------------
# 4.7 Oberösterreich
# ---------------------------------------------------------------------------

ooe := params.upper_austria

ooe_parcels := [p | some p in arable_in_area; in_upper_austria_area(p)]

fertilizer_applications(p) := object.get(p, ["operations", "fertilizer_applications"], [])

# Datum liegt im über den Jahreswechsel reichenden Sperrzeitraum [from, to]
in_winter_window(d, from_md, _) if month_day(d) >= from_md

in_winter_window(d, _, to_md) if month_day(d) <= to_md

ooe_ban_window(p) := w if {
	is_maize(p)
	some w in ooe.readily_soluble_n_ban
	w.scope == "mais"
}

ooe_ban_window(p) := w if {
	not is_maize(p)
	not is_arable_forage(p)
	some w in ooe.readily_soluble_n_ban
	w.scope == "ackerflaechen_ausser_ackerfutter"
}

violations contains {
	"rule_id": "o6_16.ooe.readily_soluble_n_ban",
	"parcel_id": p.parcel_id,
	"message": sprintf("Ausbringung leichtlöslicher stickstoffhaltiger Dünger am %v im Sperrzeitraum %v bis %v.", [a.date, w.from_month_day, w.to_month_day]),
} if {
	some p in ooe_parcels
	w := ooe_ban_window(p)
	some a in fertilizer_applications(p)
	object.get(a, "readily_soluble_n", false) == true
	in_winter_window(a.date, w.from_month_day, w.to_month_day)
}

violations contains {
	"rule_id": "o6_16.ooe.split_n_applications",
	"parcel_id": p.parcel_id,
	"message": sprintf("Stickstoffgabe mit %v kg/ha Nitrat-, Ammonium- oder Carbamid-N (> 80 kg/ha) ist zu teilen.", [a.n_available_kg_ha]),
} if {
	some p in ooe_parcels
	some a in fertilizer_applications(p)
	a.n_available_kg_ha > ooe.max_single_n_application_kg_ha
	object.get(a, "slow_release", false) == false
}

violations contains {
	"rule_id": "o6_16.ooe.no_cover_crop_variant_3",
	"parcel_id": p.parcel_id,
	"message": "Begrünungsvariante 3 (o6_6) in der Gebietskulisse Oberösterreich nicht zulässig.",
} if {
	some p in ooe_parcels
	object.get(p, ["operations", "cover_crop", "o6_6_variant"], null) == ooe.forbidden_cover_crop_variant_o6_6
}

violations contains {
	"rule_id": "o6_16.ooe.ipm_control_walk",
	"parcel_id": p.parcel_id,
	"message": "Chemisch-synthetische Pflanzenschutzmaßnahme ohne dokumentierten Kontrollgang bzw. Warndienstmeldung.",
} if {
	some p in ooe_parcels
	some a in psm_applications(p)
	a.product_type == "chemical_synthetic"
	object.get(a, "prior_field_inspection_documented", false) == false
	object.get(a, "warning_service_documented", false) == false
}

# o6_16 – Aufzeichnungen (4.1/4.2), Weiterbildung (4.4) und Bodenuntersuchung (4.5)
package oepul.o6_16

# ---------------------------------------------------------------------------
# 4.1 Betriebsbezogene Aufzeichnungen
# ---------------------------------------------------------------------------

farm_records := object.get(o16, "farm_records", {})

fertilization_plan_deadline := md_date(year, params.farm_records.plan_deadline_month_day)

farm_balance_deadline := md_date(year + 1, params.farm_records.balance_deadline_month_day_next_year)

violations contains {
	"rule_id": "o6_16.records.farm_plan_deadline",
	"parcel_id": null,
	"message": "Voraussichtliche Düngeplanung nicht bis 28.02. des Förderjahres angelegt.",
} if {
	participates_o6_16
	not farm_plan_in_time
}

farm_plan_in_time if {
	d := farm_records.fertilization_plan_date
	is_date(d)
	date_le(d, fertilization_plan_deadline)
}

violations contains {
	"rule_id": "o6_16.records.farm_balance_deadline",
	"parcel_id": null,
	"message": "Betriebliche Düngebilanzierung nicht bis 31.01. des Folgejahres abgeschlossen.",
} if {
	d := farm_records.farm_balance_completed_date
	is_date(d)
	not date_le(d, farm_balance_deadline)
}

violations contains {
	"rule_id": "o6_16.records.napv_compliance",
	"parcel_id": null,
	"message": "Düngevorgaben bzw. Aufzeichnungen gemäß § 8 Abs. 1 NAPV auf allen Flächen nicht eingehalten.",
} if {
	participates_o6_16
	object.get(farm_records, "napv_compliant", true) == false
}

# ---------------------------------------------------------------------------
# 4.2 Schlagbezogene Aufzeichnungen
# ---------------------------------------------------------------------------

field_records := object.get(o16, "field_records", {})

# Kulturflächen je Kultur in der Gebietskulisse
crop_area_in_area[name] := total if {
	some p in arable_in_area
	name := crop_key(p)
	total := sum([q.area_ha | some q in arable_in_area; crop_key(q) == name])
}

crop_key(p) := lower(crop_name(p)) if {
	is_string(crop_name(p))
	crop_name(p) != ""
} else := crop_category(p)

# Kulturen mit max. 0,30 ha je Kultur sind von schlagbezogenen Aufzeichnungen ausgenommen
field_records_required_for(name) if crop_area_in_area[name] > params.field_records.small_crop_max_ha

field_records_required if {
	some name, _ in crop_area_in_area
	field_records_required_for(name)
}

violations contains {
	"rule_id": "o6_16.records.field_records_electronic",
	"parcel_id": null,
	"message": "Schlagbezogene Aufzeichnungen sind elektronisch zu führen.",
} if {
	field_records_required
	object.get(field_records, "electronic", false) == false
}

violations contains {
	"rule_id": "o6_16.records.field_records_14_days",
	"parcel_id": null,
	"message": "Schlagbezogene Aufzeichnungen nicht innerhalb von 14 Tagen nach Ausbringung, Anbau, Bewässerung oder Ernte fertiggestellt.",
} if {
	field_records_required
	delay := object.get(field_records, "max_completion_delay_days", 0)
	delay > params.field_records.max_completion_days
}

violations contains {
	"rule_id": "o6_16.records.field_records_content",
	"parcel_id": null,
	"message": "Schlagbezogene Aufzeichnungen unvollständig (u. a. Erntemenge samt Wiegebelegen, Bewässerung, jährlicher Stickstoffsaldo).",
} if {
	field_records_required
	object.get(field_records, "content_complete", false) == false
}

# ---------------------------------------------------------------------------
# 4.4 Weiterbildung und Gewässerschutzkonzept
# ---------------------------------------------------------------------------

training_courses := object.get(o16, "training_courses", [])

course_creditable(c, topics) if {
	date_le(params.training.earliest_course_date, c.date)
	date_le(c.date, params.training.deadline)
	object.get(c, "provider_recognized", false) == true
	object.get(c, "credited_to_other_commitment", false) == false
	object.get(c, "credited_to_other_farm", false) == false
	not attendee_left_before_deadline(c)
	some t in c.topics
	t in topics
}

attendee_left_before_deadline(c) if {
	d := object.get(c, "attendee_left_farm_date", null)
	is_date(d)
	date_lt(d, params.training.deadline)
}

base_training_topics := {t | some t in params.training.topics}

vienna_training_topics := {t | some t in params.training.vienna_extra_topics}

training_hours := sum([c.hours |
	some c in training_courses
	not object.get(c, "vienna_extra", false) == true
	course_creditable(c, base_training_topics)
])

vienna_extra_training_hours := sum([c.hours |
	some c in training_courses
	object.get(c, "vienna_extra", false) == true
	course_creditable(c, vienna_training_topics)
])

default training_fulfilled := false

training_fulfilled if training_hours >= params.training.min_hours

deadline_passed(deadline) if year > date_year(deadline)

obligations contains {
	"rule_id": "o6_16.training.min_hours",
	"deadline": params.training.deadline,
	"status": obligation_status(training_fulfilled, params.training.deadline),
	"detail": sprintf("%v von 10 anrechenbaren Weiterbildungsstunden", [training_hours]),
} if {
	participates_o6_16
}

obligation_status(true, _) := "fulfilled"

obligation_status(false, deadline) := "missed" if deadline_passed(deadline)

obligation_status(false, deadline) := "open" if not deadline_passed(deadline)

violations contains {
	"rule_id": "o6_16.training.min_hours",
	"parcel_id": null,
	"message": "Weiterbildung von mindestens 10 Stunden nicht bis 31.12.2026 absolviert.",
} if {
	participates_o6_16
	not training_fulfilled
	deadline_passed(params.training.deadline)
}

default water_protection_concept_done := false

water_protection_concept_done if {
	d := o16.water_protection_concept_date
	is_date(d)
	date_le(d, params.training.concept_deadline)
}

violations contains {
	"rule_id": "o6_16.training.water_protection_concept",
	"parcel_id": null,
	"message": "Betriebsbezogenes Gewässerschutzkonzept nicht bis 31.12.2026 erstellt.",
} if {
	participates_o6_16
	not water_protection_concept_done
	deadline_passed(params.training.concept_deadline)
}

obligations contains {
	"rule_id": "o6_16.training.water_protection_concept",
	"deadline": params.training.concept_deadline,
	"status": obligation_status(water_protection_concept_done, params.training.concept_deadline),
	"detail": "einmaliges betriebsbezogenes Gewässerschutzkonzept",
} if {
	participates_o6_16
}

# ---------------------------------------------------------------------------
# 4.5 Bodenuntersuchung
# ---------------------------------------------------------------------------

# pro angefangene 5 ha Ackerfläche in der Gebietskulisse (MFA 2026) mindestens eine Probe
soil_samples_required(area_ha) := 0 if area_ha <= 0

soil_samples_required(area_ha) := ceil(area_ha / params.soil_samples.ha_per_sample) if area_ha > 0

soil_sample_base_area_ha := o16.soil_sample_base_area_ha if {
	is_number(object.get(o16, "soil_sample_base_area_ha", null))
} else := arable_in_area_ha

soil_samples := object.get(o16, "soil_samples", [])

required_parameter_set := {x | some x in params.soil_samples.required_parameters}

soil_sample_creditable(s) if {
	date_le(params.soil_samples.earliest_sampling_date, s.sampling_date)
	is_date(s.lab_submission_date)
	date_le(s.lab_submission_date, params.soil_samples.deadline)
	object.get(s, "lab_accredited", false) == true
	required_parameter_set - {x | some x in s.parameters} == set()
	object.get(s, "n_method", "") in {m | some m in params.soil_samples.n_methods}
	object.get(s, "analysis_method", "") in {m | some m in params.soil_samples.analysis_methods}
	object.get(s, "received_with_parcel_from_other_farm", false) == false
}

creditable_soil_samples := [s | some s in soil_samples; soil_sample_creditable(s)]

default soil_samples_fulfilled := false

soil_samples_fulfilled if count(creditable_soil_samples) >= soil_samples_required(soil_sample_base_area_ha)

obligations contains {
	"rule_id": "o6_16.soil.samples_per_5ha",
	"deadline": params.soil_samples.deadline,
	"status": obligation_status(soil_samples_fulfilled, params.soil_samples.deadline),
	"detail": sprintf("%v von %v erforderlichen Bodenproben", [count(creditable_soil_samples), soil_samples_required(soil_sample_base_area_ha)]),
} if {
	participates_o6_16
}

violations contains {
	"rule_id": "o6_16.soil.samples_per_5ha",
	"parcel_id": null,
	"message": sprintf("Nur %v anrechenbare Bodenproben, erforderlich %v (je angefangene 5 ha Ackerfläche in der Gebietskulisse).", [count(creditable_soil_samples), soil_samples_required(soil_sample_base_area_ha)]),
} if {
	participates_o6_16
	not soil_samples_fulfilled
	deadline_passed(params.soil_samples.deadline)
}

violations contains {
	"rule_id": "o6_16.soil.results_in_invekos_gis",
	"parcel_id": null,
	"message": sprintf("Ergebnis der Bodenprobe %v nicht im INVEKOS-GIS erfasst.", [object.get(s, "sample_id", "?")]),
} if {
	some s in creditable_soil_samples
	object.get(s, "entered_in_invekos_gis", false) == false
	deadline_passed(params.soil_samples.deadline)
}

# Zuordnung einer Bodenprobe zum Mehrfachantrag des Ziehungsjahres; neu im Herbst
# hinzugekommene Flächen können dem Folgejahr zugeordnet werden.
soil_sample_mfa_year(sampling_date, false) := date_year(sampling_date)

soil_sample_mfa_year(sampling_date, true) := date_year(sampling_date) + 1

